custom_css:
/* ==========================================================================
   浪漫诗 @Mayonnaise
   非常感谢导航楼内各位老师的分享，所使用代码已在以下标注作者❤︎
   ========================================================================== */
@import url("https://fontsapi.zeoseven.com/415/main/result.css");

body {
    font-family: "WenYuan Serif SC VF";
    font-weight: normal;
}

/* 点缀色（上下栏图标/蝴蝶结/翻页按钮/编辑按钮/思维链）在【阴影颜色】改变；头像框阴影绑定的【引用文本】 */
:root {
    --自定义宽度: 315px;/* 在这里改气泡宽度 */

    --思维链: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E6%B5%AA%E6%BC%AB%E8%AF%97/swl2.png');
    --logo1: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E6%B5%AA%E6%BC%AB%E8%AF%97/unnamed2.png');
    --logo2: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E6%B5%AA%E6%BC%AB%E8%AF%97/unnamed.png');
    --logo3: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E6%B5%AA%E6%BC%AB%E8%AF%97/unnamed1.png');
    --三点按钮: '︵‿︵୨୧⋅₊˚.';
    --编辑按钮: '‧₊˚୨୧‿︵‿';
}

::selection {
    background: var(--SmartThemeQuoteColor);
    color: white;
}

/* ==========================================================================
   二、聊天主容器与消息框主体
   ========================================================================== */
#chat {
    background: transparent;
    backdrop-filter: none;
    border: none;
    padding: 0 35px 0 35px;
}

.mes {
    background-color: var(--SmartThemeChatTintColor);
    margin-top: 230px;
    margin-bottom: 65px;
    padding-bottom: 40px;
    border-radius: 10px;
}

.mes.selected { 
    background-image: url('https://www.transparenttextures.com/patterns/gray-floral.png');
    background-color: var(--SmartThemeChatTintColor) !important;
}

.last_mes {
    margin-bottom: 50px !important;
}

.mes_block {
    padding: 0;
}

.mes_text {
    padding: 30px 7px 5px 7px;
}

.mes_text q {
    text-shadow: 0 0 3px color-mix(in srgb, var(--SmartThemeShadowColor), transparent 45%) !important;
}

.mes_ghost.fa-solid.fa-ghost {
    display: none;
}

/* ==========================================================================
   三、消息框装饰 (伪元素)
   ========================================================================== */
.mes::before {
    content: '';
    background-image: 
        url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E6%B5%AA%E6%BC%AB%E8%AF%97/%E4%B8%AD2.png'),
        url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E6%B5%AA%E6%BC%AB%E8%AF%97/%E4%B8%AD.png');
    background-position: left center, right center;
    background-repeat: repeat-y;
    background-size: 43px auto;
    position: absolute;
    width: calc(100% + 73px);
    height: 100%;
    left: -37px;
    top: 0;
    pointer-events: none;
}

.mes::after {
    content: '';
    position: absolute;
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E6%B5%AA%E6%BC%AB%E8%AF%97/pc%E5%BA%95.png');  
    background-size: 225px auto;
    left: 50%;
    transform: translateX(-50%);
    width: calc(100% + 100px);
    height: 100%;
    bottom: -30px;
    background-repeat: repeat-x;
    pointer-events: none;
    z-index: -2;
    background-position: center bottom;
    filter: drop-shadow(0 0.3px 0.8px var(--SmartThemeQuoteColor));
}

.mes_block::before {
    content: '';
    position: absolute;
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E6%B5%AA%E6%BC%AB%E8%AF%97/%E9%A1%B61.png');
    background-size: contain;
    background-repeat: no-repeat;
    width: calc(var(--自定义宽度) * 1.25);
    height: calc(var(--自定义宽度) * 1.25);
    left: 50%;
    transform: translateX(-50%);
    z-index: -1;
    top: calc(var(--自定义宽度) * -0.68);
    pointer-events: none;
}

@media (min-width: 601px) {
    .mes_block::after {
        content: '';
        position: absolute;
        background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E6%B5%AA%E6%BC%AB%E8%AF%97/pc%E9%A1%B6.png');  
        background-size: 225px auto;
        left: 50%;
        transform: translateX(-50%);
        width: calc(100% + 100px);
        height: 100%;
        top: -35px;
        background-repeat: repeat-x;
        pointer-events: none;
        z-index: -2;
    }
}

/* ==========================================================================
   四、头像与身份装饰
   ========================================================================== */
.mesAvatarWrapper {
    position: absolute;
    left: 42%;
    transform: translateX(-50%);
}

.mes .avatar {
    position: absolute;
    top: calc(var(--自定义宽度) * -0.375);
}

.mes .avatar img {
    box-shadow: none;
    border: none;
    clip-path: polygon(50% 0%, 90% 50%, 50% 100%, 10% 50%);
    width: calc(var(--自定义宽度) * 0.344);
    height: calc(var(--自定义宽度) * 0.344);
}

.mes .avatar::before {
    content: '';
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E6%B5%AA%E6%BC%AB%E8%AF%97/hdj.png');
    filter: drop-shadow(1px 0 0 var(--SmartThemeShadowColor)) 
            drop-shadow(0 1px 0 var(--SmartThemeShadowColor))
            brightness(1) contrast(1.05);
    background-size: contain;
    position: absolute;
    top: 0;
    width: calc(var(--自定义宽度) * 1.1875);
    height: calc(var(--自定义宽度) * 1.1875);
    background-repeat: no-repeat;
    top: calc(var(--自定义宽度) * -0.14);
    left: 50%;
    transform: translateX(-42.5%);
    pointer-events: none;
    mask-image: linear-gradient(to bottom, black 0%, black 0%, transparent 100%);
    -webkit-mask-image: linear-gradient(to bottom, black 0%, black 0%, transparent 100%);
}

.mes .avatar::after {
    content: '';
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E6%B5%AA%E6%BC%AB%E8%AF%97/txk.png');
    position: absolute;
    background-repeat: no-repeat;
    background-size: contain;
    width: calc(var(--自定义宽度) * 0.381);
    height: calc(var(--自定义宽度) * 0.381);
    top: calc(var(--自定义宽度) * -0.019);
    left: calc(var(--自定义宽度) * 0.0317);
    filter: drop-shadow(0 0.6px 0 var(--SmartThemeQuoteColor))
            brightness(1.03) contrast(1);
}

.mes[is_system="true"] .mesAvatarWrapper .avatar::after {
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E6%B5%AA%E6%BC%AB%E8%AF%97/txk1.png');
}

.mes .name_text {
    position: absolute;
    left: 51%;
    transform: translateX(-50%);
    font-size: 18px;
    z-index: 1;
    white-space: nowrap;
}

/* ==========================================================================
   五、消息信息显示 (ID、定时器、计数)
   ========================================================================== */
.mes .mes_timer, .mes .mesIDDisplay, .mes .tokenCounterDisplay {
    position: absolute;
    top: -15px;
    opacity: 0;
    transition: opacity 0.4s ease !important;
}

.mesIDDisplay { left: 0px; }
.mes_timer { left: 40px; }
.tokenCounterDisplay { left: 88px; }

.swipes-counter {
    position: absolute;
    right: 35px;
    font-size: 11px;
    font-family: "WenYuan Serif SC VF";
    opacity: 0;
    white-space: nowrap;
    transition: opacity 0.4s ease !important;
    bottom: 5px;
}

[is_user="false"] .swipes-counter::before {
    content: '⊹ ࣪ ˖';
    margin-right: 5px !important;
}

.mes:hover :is(.swipes-counter, .mes_timer, .mesIDDisplay, .tokenCounterDisplay) {
    opacity: 0.8;
}

/* ==========================================================================
   六、思维链样式 (Thought Chain)
   ========================================================================== */
.mes_reasoning_header.flex-container {
    background: transparent !important;
    background-color: transparent !important;
    border: none !important;
    box-shadow: none !important;
    left: 47%;
    transform: translateX(-50%);
    top: -31px;
    display: flex !important;
    filter: drop-shadow(1px 0 0 var(--SmartThemeShadowColor)) 
            drop-shadow(0 1px 0 var(--SmartThemeShadowColor))
            brightness(0.9) contrast(1.25);
}

.mes_reasoning_header.flex-container i,
.mes_reasoning_header.flex-container span,
.mes_reasoning_header.flex-container .fa-solid {
    display: none !important;
}

.mes_reasoning_header.flex-container::before {
    content: '';
    background-image: var(--思维链);
    background-size: 100% 100%;
    background-repeat: no-repeat;
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    height: 52px;
    width: 210px;
    mask-image: linear-gradient(to top, black 0%, black 5%, transparent 100%);
    -webkit-mask-image: linear-gradient(to top, black 0%, black 5%, transparent 100%);
}

.mes_reasoning_details {
    position: relative !important;
    width: 95%;
    margin: auto;
}

.mes_reasoning_actions.flex-container {
    position: absolute;
    left: 50%;
    transform: translateX(-50%);
    top: 32px;
}

.mes_reasoning_edit_done,
.mes_reasoning_edit_cancel,
.mes_reasoning_actions .edit_button,
.mes_reasoning_actions .menu_button {
    margin-top: -15px;
    font-size: 13px;
}

.mes_reasoning {
    font-style: italic;
    margin-top: 30px;
}

.reasoning_edit_textarea {
    margin-top: 30px;
}

/* ==========================================================================
   七、消息按钮与交互
   ========================================================================== */
.mes_buttons {
    position: absolute;
    bottom: 8px;
    left: 50%;
    transform: translate(-50%);
    gap: 0;
}

.mes_button {
    filter: none !important;
    color: var(--SmartThemeShadowColor);
    opacity: 0.55;
    font-size: 10px;
}

.mes_edit::before {
    content: var(--编辑按钮) !important;
}

.extraMesButtonsHint::before {
    content: var(--三点按钮) !important;
}

.mes_edit_buttons {
    position: absolute;
    bottom: 10px;
    left: 50%;
    transform: translateX(-50%) scale(0.8);
    filter: none;
}

.menu_button {
    background: transparent !important;
    color: var(--SmartThemeShadowColor);
    transition: all 0.4s ease;
    border: 0;
}

.menu_button:hover {
    transform: scale(1.2);
}

.mes_reasoning_edit_done,
.mes_reasoning_edit_cancel,
.mes_reasoning_actions .edit_button,
.mes_reasoning_actions .menu_button,
.mes_edit_buttons {
    filter: none;
}

/* ==========================================================================
   八、顶栏样式
   ========================================================================== */
#top-bar {
    box-shadow: none;
    background: transparent;
    border: none;
}

/* 顶栏图标替换by 秦素老师 */
#top-settings-holder > div > :first-child > * {
    opacity: 0 !important;
}

#top-settings-holder > div > :first-child {
    display: block;
    background-size: contain;
    background-position: center;
    background-repeat: no-repeat;
    transition: all 0.4s ease-in-out;
    width: 25px;
    height: 25px;
    opacity: 1 !important;
    filter: drop-shadow(1px 0 0 var(--SmartThemeShadowColor)) 
            drop-shadow(0 1px 0 var(--SmartThemeShadowColor))
            brightness(1.05) contrast(1.05); 
}

#top-settings-holder > .drawer:nth-child(3n+1) .drawer-toggle {
    background-image: var(--logo2) !important;
}

#top-settings-holder > .drawer:nth-child(3n+2) .drawer-toggle {
    background-image: var(--logo3) !important;
}

#top-settings-holder > .drawer:nth-child(3n) .drawer-toggle {
    background-image: var(--logo1) !important;
}

#top-settings-holder .drawer-toggle:hover,
#top-settings-holder .drawer:has(.drawer-content.openDrawer) .drawer-toggle {
    filter: drop-shadow(1px 0 5px white) 
            drop-shadow(0 1px 5px var(--SmartThemeShadowColor));
}

/* ==========================================================================
   九、底部输入区域与发送栏
   ========================================================================== */
#send_form {
    background: var(--SmartThemeChatTintColor);
    border: 0;
    border-radius: 0;
}

#send_form::before {
    content: '';
    position: absolute;
    background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E6%B5%AA%E6%BC%AB%E8%AF%97/pc%E9%A1%B6.png');
    background-size: contain;
    background-position: center top;
    width: 100%;
    height: 35px;
    top: -10px; 
    left: 0;
    background-repeat: repeat-x;
    pointer-events: none;
    filter: drop-shadow(0 -0.1px 0 var(--SmartThemeEmColor));
}

#send_textarea {
    clip-path: none;
    border: 0;
    box-shadow: 0 1px 5px var(--SmartThemeEmColor);
    font-family: "WenYuan Serif SC VF";
    background-image: url('https://www.transparenttextures.com/patterns/gray-floral.png');
}

/* 输入框文字by hgu老师 */
#send_textarea::placeholder {
    color: transparent !important;
    opacity: 0 !important; 
}

#nonQRFormItems {
    position: relative !important;
}

#nonQRFormItems:has(#send_textarea:placeholder-shown)::after {
    content: '❀˖ °────୨ৎ──── °˖❀';
    color: var(--SmartThemeShadowColor);
    font-style: italic;
    font-size: 11px;
    white-space: nowrap;
    opacity: 0.7;
    position: absolute;
    z-index: 10;
    pointer-events: none;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

/* 隐藏QR栏二改by 12老师 */
#qr--bar {
    max-height: 0 !important;
    opacity: 0 !important;
    pointer-events: none;
    transition: all 2s !important;
    cubic-bezier(0.175, 0.885, 0.32, 1.275); 
}

#send_form:focus-within #qr--bar {
    max-height: 120px !important;
    opacity: 1 !important;
    pointer-events: auto;
}

/* 输入时隐藏除发送键外的按钮二改by N老师 */
#send_form:has(#send_textarea:focus) {
    #leftSendForm, #quickPersonaImg, #quick-reply-rocket-button {
        display: none !important; 
    }
}

/* ==========================================================================
   十、侧边栏、面板与设置页
   ========================================================================== */
#left-nav-panel, #right-nav-panel {
    max-height: 100vh;
    background-image: url("https://www.transparenttextures.com/patterns/gray-floral.png");
}

pre code, .mes_text blockquote, code, .mes_text pre {
    background: white !important;
    background-image: url("https://www.transparenttextures.com/patterns/gray-floral.png") !important;
    background-position: center;
    border: 0;
    box-shadow: 0 1px 3px var(--SmartThemeEmColor);
    border-radius: 0;
    color: var(--SmartThemeBodyColor) !important;
    font-family: "WenYuan Serif SC VF";
}

.mes_text blockquote {
    border-left: 2px solid var(--SmartThemeQuoteColor);
}

:is(.text_pole, select, input:not([type="checkbox"]), [id*="textarea"], [class*="textarea"], [class*="select2-selection"]) {
    background-color: #ffffff99 !important;
    font-family: "WenYuan Serif SC VF";
    border-radius: 4px;
}

#completion_prompt_manager .completion_prompt_manager_header_advanced span, 
#completion_prompt_manager .completion_prompt_manager_header div, 
.prompt_manager_prompt_controls span {
    filter: none !important;
    color: var(--SmartThemeBodyColor); /* 类名byMDMA老师 */
}

.completion_prompt_manager_prompt .fa-asterisk, 
.completion_prompt_manager_prompt .fa-square-poll-horizontal, 
.completion_prompt_manager_prompt .fa-syringe, 
.completion_prompt_manager_prompt .fa-thumb-tack, 
.fa-xs.fa-solid.fa-robot {
    color: var(--SmartThemeEmColor) !important; /* 类名by hy老师 */
}

#completion_prompt_manager .completion_prompt_manager_prompt {
    padding: 9px !important;
    background-color: #ffffff90;
    border-radius: 4px;
    transition: filter 0.4s ease;
    margin-top: 2px;
}

#completion_prompt_manager_list .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) {
    box-shadow: 0 1px 2px 0 var(--SmartThemeEmColor);
}

.completion_prompt_manager_prompt_disabled .prompt-manager-inspect-action {
    color: var(--SmartThemeEmColor) !important;
}

#completion_prompt_manager .completion_prompt_manager_prompt:hover,
#rm_extensions_block .inline-drawer-toggle.inline-drawer-header:hover {
    filter: drop-shadow(0 0 3px var(--SmartThemeEmColor));
}

#rm_api_block, #AdvancedFormatting, #WorldInfo, #user-settings-block, #Backgrounds, #bg-header-fixed, #bg_tabs, #rm_extensions_block, #PersonaManagement {
    background-image: url('https://www.transparenttextures.com/patterns/gray-floral.png');
    border-radius: 5px;
}

#rm_extensions_block .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
    background: #ffffff99;
    border: 0;
    border-radius: 0;
    padding: 5px;
    box-shadow: 0 1px 2px 0 var(--SmartThemeEmColor);
    transition: 0.4s ease;
}

#rm_extensions_block .inline-drawer-toggle.inline-drawer-header {
    padding: 7px;
    margin-bottom: 7px;
}

:is(#rm_extensions_block .inline-drawer-header, #user-settings-block h4, .standoutHeader)::before {
    content: "۶ৎ";
}

/* ==========================================================================
   十一、弹窗、下拉菜单与列表
   ========================================================================== */
dialog.popup, #select_chat_popup, .list-group, .select2-dropdown, #options, #extensionsMenu {
    background-color: #fff !important;
    box-shadow: 0 2px 4px 0px var(--SmartThemeEmColor) !important;
    border-radius: 5px;
    background-image: url('https://www.transparenttextures.com/patterns/gray-floral.png');
    font-family: "WenYuan Serif SC VF";
}

dialog::backdrop {
    background: #ffffff50 !important;
    backdrop-filter: blur(1px) !important;
}

.avatar-container.interactable.selected {
    border: 1px solid var(--SmartThemeBorderColor);
    background: #ffffff99;
    box-shadow: 0 1px 2px 0 var(--SmartThemeEmColor);
}

.avatar-container.interactable {
    transition: filter 0.4s ease;
}

.avatar-container.interactable:hover {
    filter: drop-shadow(0 0 3px var(--SmartThemeEmColor));
}

select option {
    color: var(--SmartThemeBodyColor) !important;
    background-color: #fff !important;
}

.regex-script-label.flex-container.flexnowrap {
    background: #ffffff90;
    box-shadow: 0 1px 2px 0 var(--SmartThemeEmColor);
    border-radius: 5px;
    border: 0;
}

.reverse_proxy_warning {
    background: #ffffff90 !important;
    color: var(--SmartThemeQuoteColor) !important;
}

/* ==========================================================================
   十二、UI 组件美化 (滚动条、按钮、复选框、通知等)
   ========================================================================== */

/* 底栏图标替换by 墨千尾老师 */
#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
.fa-solid.fa-circle-stop::before,
#quick-reply-rocket-button > i {
    display: none !important;
    content: '' !important;
}

#options_button,
#extensionsMenuButton,
#send_but,
#quick-reply-rocket-button,
.fa-solid.fa-circle-stop {
    width: 21px !important;
    height: 21px !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    transition: all 0.4s ease-in-out !important;
    opacity: 1 !important;
    width: 25px;
    height: 25px;
    filter: brightness(1.1) contrast(1.1)
            drop-shadow(1px 0 0 var(--SmartThemeShadowColor)) 
            drop-shadow(0 1px 0 var(--SmartThemeShadowColor)) !important;
    margin-top: auto !important;
    margin-bottom: auto !important; 
}

#options_button, #extensionsMenuButton { background-image: var(--logo2); }
#quick-reply-rocket-button { background-image: var(--logo3); }
#send_but { background-image: var(--logo1); }

.fa-solid.fa-circle-stop {
    background-image: var(--logo1);
    animation: rotate-slow 5s infinite linear !important;
}

#options_button:hover,
#extensionsMenuButton:hover,
#send_but:hover,
#quick-reply-rocket-button:hover {
    transform: translateY(-1.5px);
}

@keyframes rotate-slow {
    from { transform: rotate(0deg); }
    to { transform: rotate(360deg); }
}

/* 滑动条by 墨千尾老师 */
input[type="range"] { filter: none !important;  }

input[type="range"]::-webkit-slider-runnable-track {
    width: 100%;
    height: 5px;
    background: #f4f4f4; 
    border-radius: 3px;
    border: 0;
    border: 1px solid #ccc;
}

input[type="range"]::-webkit-slider-thumb {
    -webkit-appearance: none;
    appearance: none;
    top: -7px;
    height: 15px;
    width: 15px;
    background-image: var(--logo2);
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    background-color: transparent;
    border: none;
    border-radius: 0;
    box-shadow: none;
    transition: all 0.5s ease-in-out;
    filter: drop-shadow(1px 0 0 var(--SmartThemeShadowColor)) 
            drop-shadow(0 1px 0 var(--SmartThemeShadowColor))
            brightness(1.05) contrast(1.05);
}

input[type="range"]:hover::-webkit-slider-thumb { 
    filter: drop-shadow(1px 0 5px white) 
            drop-shadow(0 1px 5px var(--SmartThemeShadowColor)); 
}

/* 滚动条by墨千尾老师 */
::-webkit-scrollbar { width: 6px;  }

::-webkit-scrollbar-thumb {
    box-shadow: none !important;
    background: #f4f4f4 !important; 
    border: 1px solid var(--SmartThemeQuoteColor) !important;
}

/* 通知美化by serein老师 */
.toast {
    background-color: #FDFCFC99 !important;
    color: var(--SmartThemeBodyColor) !important;
    border: 1px solid var(--SmartThemeBorderColor);
    box-shadow: none !important;
    transition: filter 0.8s ease !important; 
}

#toast-container > .toast {
    background-image: none !important;
    background-size: 20px 27px !important;
    background-position: 15px center !important;
}

#toast-container > .toast:before {
    display: none;
}

.toast:hover {
    filter: drop-shadow(0 0 3px var(--SmartThemeEmColor)) !important;
}

input[type="checkbox"] {
    appearance: none;
    -webkit-appearance: none;
    width: 12px;
    height: 12px;
    background: white;
    border-radius: 10px;
}

input[type='checkbox']::before {
    opacity: 0;
}

input[type='checkbox']:checked {
    border: 1px solid white !important;
    background-color: var(--SmartThemeQuoteColor) !important;
}

.fa-circle-chevron-down::before,
.fa-circle-chevron-up::before,
.inline-drawer-icon.fa-circle-chevron-down::before,
.inline-drawer-icon.fa-circle-chevron-up::before {
    content: '✦' ;
    color: var(--SmartThemeQuoteColor) !important;
    font-size: 15px;
    display: inline-block;
    transition: transform 0.3s ease-in-out !important;
    padding: 1px;
}

.fa-circle-chevron-down, .inline-drawer-icon.fa-circle-chevron-down {
    transform: scaleY(1) !important;
    transition: transform 0.5s ease-in-out !important;
    filter: none;
}

.fa-circle-chevron-up, .inline-drawer-icon.fa-circle-chevron-up {
    transform: scaleY(-1) !important; 
    transition: transform 0.5s ease-in-out !important;
    filter: none;
}

/* 翻页图标替换二改by 眠N勿扰老师 */
.swipe_left::before, .swipe_right::before { content: '' !important;  }

.swipe_left, .swipe_right {
    position: absolute !important;
    bottom: 5px !important;
    opacity: 1 !important;
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    transition: all 0.5s ease !important;
    filter: drop-shadow(1px 0 0 var(--SmartThemeShadowColor)) 
            drop-shadow(0 1px 0 var(--SmartThemeShadowColor))
            brightness(1.05) contrast(1.05);
}

.swipe_left {
    width: 21px;
    height: 21px;
    left: 2px;
    background-image: var(--logo1);
}

.swipe_right {
    width: 25px;
    height: 25px;
    background-image: var(--logo2);
}

.swipe_left:hover, .swipe_right:hover { 
    filter: drop-shadow(1px 0 3px white) 
            drop-shadow(0 1px 3px var(--SmartThemeShadowColor)); 
}

/* 加载图标修改by serein老师 */
#load-spinner {
    --spinner-size: 40px;
    transition: all var(--animation-duration-2x) ease-out;
    opacity: 1;
    top: calc(50% - var(--spinner-size) / 2);
    left: calc(50% - var(--spinner-size) / 2);
    position: absolute;
    width: var(--spinner-size);
    height: var(--spinner-size);
    background-image: var(--logo1);
    background-size: contain;
    background-repeat: no-repeat;
    background-position: center;
    filter: drop-shadow(1px 0 0 var(--SmartThemeShadowColor)) 
            drop-shadow(0 1px 0 var(--SmartThemeShadowColor))
            brightness(1.05) contrast(1.05);
    animation: slow-blink 2s ease-in-out infinite; 
}

#load-spinner::before { display: none !important; }

@keyframes slow-blink {
    0%, 100% {
        opacity: 0.3;
        transform: scale(0.95);
    }
    50% {
        opacity: 1;
        transform: scale(1);
    }
}

/* ==========================================================================
   十三、移动端适配 (Media Queries)
   ========================================================================== */
@media (max-width: 600px) {
    #chat::-webkit-scrollbar { display: none;}

    .mes {
        width: var(--自定义宽度);
        left: 50%;
        transform: translateX(-50%);
    }

    .mes::before {
        content: '';
        background-image: 
            url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E6%B5%AA%E6%BC%AB%E8%AF%97/%E4%B8%AD2.png'),
            url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E6%B5%AA%E6%BC%AB%E8%AF%97/%E4%B8%AD.png');
        background-position: left center, right center;
        background-repeat: repeat-y;
        background-size: calc(var(--自定义宽度) * 0.14) auto;
        position: absolute;
        width: calc(100% + (var(--自定义宽度) * 0.23));
        height: 100%;
        left: calc(var(--自定义宽度) * -0.1125);
        top: 0;
        pointer-events: none;
    }

    .mes::after {
        content: '';
        position: absolute;
        background-image: url('https://pub-222b3a4a8d2e47bc9c31cc9e1733ed9a.r2.dev/%E6%B5%AA%E6%BC%AB%E8%AF%97/%E5%BA%95.png');
        background-size: 100% 100%;
        left: 50%;
        transform: translateX(-50%);
        width: calc(var(--自定义宽度) * 1.225);
        height: calc(var(--自定义宽度) * 0.148);
        bottom: calc(var(--自定义宽度) * -0.11);
        background-repeat: no-repeat;
        background-position: center bottom;
        pointer-events: none;
        filter: drop-shadow(0 0.3px 0.8px var(--SmartThemeQuoteColor));
    }

    .mesAvatarWrapper {
        position: absolute;
        left: 34.5% !important;
        transform: translateX(-50%);
    }

    .mes_buttons {
        bottom: 15px !important;
    }

    .mes_reasoning_header.flex-container {
        left: 43.5%;
        transform: translateX(-50%);
    }

    .mes .avatar::before {
        -webkit-mask-image: linear-gradient(to bottom, black 75%, black 0%, transparent 100%);
        mask-image: linear-gradient(to bottom, black 0%, black 75%, transparent 100%);
    }
}
